//! sparkopy reads one table through Spark Connect and writes it to one local
//! Parquet file. It streams: each Arrow batch that Spark sends is written to the
//! file as it arrives, so the whole table is never held in memory.
//!
//! Usage: `sparkopy --spark-uri sc://HOST:15002 --database DB --table TABLE --output PATH`

mod export;
#[cfg(test)]
mod parity_tests;
#[cfg(test)]
mod tests;

/// The Spark Connect messages and gRPC client, generated by build.rs from the
/// Spark v3.5.1 protobuf files in proto/.
#[allow(clippy::all, clippy::pedantic, dead_code)]
mod pb {
    tonic::include_proto!("spark.connect");
}

use std::ffi::OsString;
use std::future::Future;
use std::io::Write;
use std::process::ExitCode;

use clap::Parser;
use clap::builder::NonEmptyStringValueParser;

/// Exit statuses.
const EXIT_OK: u8 = 0;
const EXIT_ERROR: u8 = 1;
const EXIT_USAGE: u8 = 2;

/// The parsed command line.
#[derive(Parser, Debug)]
#[command(
    name = "sparkopy",
    about = "Export one Spark Connect table to one Parquet file",
    override_usage = "sparkopy --spark-uri sc://HOST:15002 --database DB --table TABLE --output PATH"
)]
pub(crate) struct Options {
    /// Spark Connect URI, such as sc://HOST:15002
    #[arg(long, value_name = "URI", value_parser = NonEmptyStringValueParser::new())]
    pub spark_uri: String,
    /// Database that holds the table
    #[arg(long, value_name = "DB", value_parser = NonEmptyStringValueParser::new())]
    pub database: String,
    /// Table to export
    #[arg(long, value_name = "TABLE", value_parser = NonEmptyStringValueParser::new())]
    pub table: String,
    /// Path of the Parquet file to write
    #[arg(long, value_name = "PATH", value_parser = NonEmptyStringValueParser::new())]
    pub output: String,
}

fn main() -> ExitCode {
    let runtime = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .expect("start the tokio runtime");
    let code = runtime.block_on(run(
        std::env::args_os(),
        &mut std::io::stderr(),
        interrupted(),
    ));
    ExitCode::from(code)
}

/// Completes at the first SIGINT or SIGTERM.
async fn interrupted() {
    use tokio::signal::unix::{SignalKind, signal};
    let mut term = signal(SignalKind::terminate()).expect("install the SIGTERM handler");
    tokio::select! {
        _ = tokio::signal::ctrl_c() => {}
        _ = term.recv() => {}
    }
}

/// The whole command. It returns the exit status. When `interrupt` completes
/// first, the export stops, its temporary file is removed and the status is 1.
pub(crate) async fn run<I, T>(
    args: I,
    stderr: &mut dyn Write,
    interrupt: impl Future<Output = ()>,
) -> u8
where
    I: IntoIterator<Item = T>,
    T: Into<OsString> + Clone,
{
    let o = match Options::try_parse_from(args) {
        Ok(o) => o,
        Err(e) => {
            // --help prints to stdout and exits 0; every other parse error is a usage error.
            if e.use_stderr() {
                let _ = write!(stderr, "{}", e.render());
                return EXIT_USAGE;
            }
            let _ = e.print();
            return EXIT_OK;
        }
    };
    let result = tokio::select! {
        result = export::export(&o, stderr) => result,
        () = interrupt => Err(anyhow::anyhow!("interrupted")),
    };
    match result {
        Ok(()) => EXIT_OK,
        Err(e) => {
            let _ = writeln!(
                stderr,
                "sparkopy: export of {}.{} failed: {e:#}",
                o.database, o.table
            );
            EXIT_ERROR
        }
    }
}
